code_examples.code:
.flag {
  width: 900px;
  height: 600px;
  position: relative;          /* reference point for the blue box */
  background-color: #ce1126;
}
.flag > div {                   /* blue band */
  background-color: #002868;
  width: 100%;
  height: 300px;
  position: absolute;
  top: 150px;                   /* a quarter of 600px */
}
.flag > div > div {             /* white circle */
  background-color: white;
  width: 200px;
  height: 200px;
  border-radius: 50%;
  position: absolute;
  top: 50px;                    /* (300 - 200) / 2 */
  left: 350px;                  /* (900 - 200) / 2 */
}
p {
  font-size: 5rem;
  color: white;
  text-align: center;
  margin: 0;
  padding: 0;
}
.flag > div div p {
  color: black;                 /* only the text inside the circle */
}

solution_code.code:
.flag { width: 900px; height: 600px; position: relative; background-color: #ce1126; }
.flag > div { background-color: #002868; height: 300px; width: 100%; position: absolute; top: 150px; }
.flag > div > div { background-color: white; position: absolute; height: 200px; width: 200px; border-radius: 50%; top: 50px; left: 350px; }
p { font-size: 5rem; color: white; text-align: center; padding: 0; margin: 0; }
.flag > div div p { color: black; }
